<script lang="ts">import {onMount} from 'svelte';import QRCode from 'qrcode';export let id='';let session:any=null;let qr='';let copied=false;onMount(async()=>{session=await (await fetch('/api/sessions/'+id)).json();qr=await QRCode.toDataURL(`${location.origin}/room/${session.room_slug}`,{width:280,margin:1})});async function copy(){await navigator.clipboard?.writeText(`${location.origin}/room/${session.room_slug}`);copied=true;setTimeout(()=>copied=false,1500)}</script>
{#if session}<div class="reveal" role="dialog" tabindex="-1" aria-label={'Game night session for '+session.game_title_snapshot}><button class="exit" aria-label="Exit session view" on:click={()=>history.back()}>×</button><section class="panel"><img src={qr} alt={'QR code for '+session.game_title_snapshot+' room — URL: '+location.origin+'/room/'+session.room_slug}/><h1>{session.game_title_snapshot}</h1><code>{location.origin}/room/{session.room_slug}</code><button class="copy" on:click={copy}>{copied?'Copied':'Copy URL'}</button></section></div>{/if}
<style>.reveal{min-height:100vh;display:grid;place-items:center;background:#15141b}.exit{position:fixed;top:24px;right:24px;background:#1e1c27aa;color:#edecee;border:1px solid #29263c;border-radius:8px;font-size:24px;width:44px;height:44px}.panel{display:flex;flex-direction:column;align-items:center;gap:20px;padding:40px;background:#15141bcc;border:1px solid #3d375e;border-radius:20px;box-shadow:0 0 48px #a277ff33}.panel img{width:280px;height:280px;background:#edecee;padding:12px}.panel h1{font-size:48px;margin:0}.panel code{color:#6d6d6d}.copy{background:transparent;color:#edecee;border:1px solid #29263c;border-radius:8px;padding:8px 14px}@media(max-width:600px){.panel{padding:24px}.panel img{width:240px;height:240px}.panel h1{font-size:32px}}</style>
